import React, { useEffect, useState } from 'react';
import { useFocusEffect } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Notifications from 'expo-notifications';
import {
  View,
  Text,
  FlatList,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  Alert,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  deleteDoc,
  doc,
  updateDoc,
} from 'firebase/firestore';
import { firestore, auth } from '../services/firebaseConfig';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import type { ListaRotasPrincipais } from '../types';
import { LinearGradient } from 'expo-linear-gradient';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { confirmAction } from '../utils/confirmAction';

type NavigationProp = NativeStackNavigationProp<ListaRotasPrincipais, 'Escalas'>;

interface Escala {
  id: string;
  data: string;
  [key: string]: any;
}

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
  // Adicione outros UIDs aqui
];

export default function TelaListaEscalas(): JSX.Element {
  const navigation = useNavigation<NavigationProp>();
  const [escalas, setEscalas] = useState<Escala[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const escalasQuery = query(
      collection(firestore, 'escalas'),
      orderBy('criadoEm', 'desc')
    );

    const unsubscribe = onSnapshot(escalasQuery, (querySnapshot) => {
      const data = querySnapshot.docs.map(doc => {
        const docData = doc.data();
        let dataFormatada = '';
        if (docData.data) {
          dataFormatada = docData.data;
        } else if (docData.criadoEm?.toDate) {
          dataFormatada = docData.criadoEm.toDate().toLocaleDateString();
        }
        return {
          id: doc.id,
          data: dataFormatada,
          ...docData,
        } as Escala;
      });
      setEscalas(data);
      setLoading(false);
    }, (error) => {
      console.log('Erro ao buscar dados:', error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  // limpa flag local e badge ao entrar na tela
  useFocusEffect(
    React.useCallback(() => {
      let mounted = true;
      const limparBadge = async () => {
        try {
          // limpa contador local
          await AsyncStorage.removeItem('nova_escala');
          // limpa contador remoto (para todos)
          try {
            const metaRef = doc(firestore, 'meta', 'escalas');
            await updateDoc(metaRef, { newCount: 0, lastClearedBy: auth.currentUser?.uid ?? null, lastClearedAt: new Date() });
          } catch (err) {
            // se falhar ao atualizar remoto, não bloqueia
            console.log('Erro ao limpar contador remoto', err);
          }
          await Notifications.setBadgeCountAsync(0);
        } catch (e) {
          console.log('Erro ao limpar badge/flag', e);
        }
      };
      if (mounted) limparBadge();
      return () => { mounted = false; };
    }, [])
  );

  const excluirEscala = async (escala: Escala) => {
    if (!uidAtual || !UIDS_PERMITIDOS.includes(uidAtual)) return;
    confirmAction({
      title: 'Excluir escala',
      message: `Deseja realmente excluir a escala "${escala.data || escala.id}"? Esta ação não pode ser desfeita.`,
      onConfirm: async () => {
        try {
          await auth.currentUser?.getIdToken(true);
          await deleteDoc(doc(firestore, 'escalas', escala.id));
          setEscalas(prev => prev.filter(item => item.id !== escala.id));
        } catch (error: any) {
          console.log('Erro ao excluir escala:', error);
        }
      },
    });
  };

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  const renderItem = ({ item, index }: { item: Escala; index: number }) => {
    const cardColors = index % 3 === 0
      ? ['#27305E', '#171B36']
      : index % 3 === 1
        ? ['#2A2555', '#191D38']
        : ['#233961', '#171C37'];

    return (
    <View style={styles.escalaItem}>
      <LinearGradient
        colors={index % 2 === 0 ? ['#42E5D2', '#31547D', '#26344E'] : ['#FFC76A', '#77562D', '#26344E']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.escalaGradientBorder}
      >
      <LinearGradient
        colors={cardColors}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.escalaContent}
      >
        <View style={styles.cardGlow} />
        <TouchableOpacity
          style={styles.escalaInfo}
          onPress={() => navigation.navigate('DetalhesEscala', { id: item.id })}
          activeOpacity={0.82}
        >
          <View style={[styles.iconeData, index % 2 !== 0 && styles.iconeDataAlternativo]}>
            <MaterialCommunityIcons
              name="calendar-month-outline"
              size={22}
              color={index % 2 === 0 ? '#56E6D3' : '#FFD071'}
            />
          </View>
          <View style={styles.escalaDados}>
            <Text style={styles.escalaLabel}>
              {item.data ? 'ESCALA PROGRAMADA' : 'IDENTIFICADOR'}
            </Text>
            <Text style={styles.escalaTexto} numberOfLines={1}>
              {item.data || item.id}
            </Text>
            <View style={styles.escalaDetalhes}>
              <Text style={styles.escalaDetalhesTexto}>Ver detalhes</Text>
              <MaterialCommunityIcons name="chevron-right" size={14} color="#8DA4C1" />
            </View>
          </View>
        </TouchableOpacity>
        {permitido && (
          <TouchableOpacity
            style={styles.botaoExcluir}
            onPress={() => excluirEscala(item)}
            activeOpacity={0.8}
            accessibilityLabel="Excluir escala"
          >
            <MaterialCommunityIcons name="trash-can-outline" size={18} color="#FF7890" />
          </TouchableOpacity>
        )}
      </LinearGradient>
      </LinearGradient>
    </View>
    );
  };

  return (
    <LinearGradient
      colors={['#091629', '#0C172B', '#101B30']}
      style={styles.bg}
      start={{ x: 0, y: 0 }}
      end={{ x: 0, y: 1 }}
    >
      <View style={styles.container}>
        <LinearGradient
          colors={['#12223B', '#0D192D']}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={styles.headerBar}
        >
          <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.navigate('Inicio')}>
            <MaterialCommunityIcons name="home-variant-outline" size={22} color="#63E7CC" />
          </TouchableOpacity>
          <View style={styles.headerCentro}>
            <Text style={styles.headerEyebrow}>MINISTÉRIO DE LOUVOR</Text>
            <Text style={styles.headerTitle}>Lista de Escalas</Text>
          </View>
          <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.goBack()}>
            <MaterialCommunityIcons name="arrow-left" size={22} color="#B8C9E0" />
          </TouchableOpacity>
        </LinearGradient>
        <View style={styles.secaoCabecalho}>
          <View style={styles.secaoTituloArea}>
            <Text style={styles.secaoEyebrow}>ORGANIZAÇÃO DA EQUIPE</Text>
            <View style={styles.secaoTituloLinha}>
              <Text style={styles.secaoTitulo}>Escalas</Text>
              <View style={styles.contadorEscalas}>
                <Text style={styles.contadorEscalasTexto}>{escalas.length}</Text>
              </View>
            </View>
          </View>
          {permitido && (
            <TouchableOpacity
              style={styles.topCreateButton}
              onPress={() => navigation.navigate('CriarEscala')}
              activeOpacity={0.86}
            >
              <LinearGradient
                colors={['#FFC76A', '#FF944C']}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.topCreateButtonGradient}
              >
                <MaterialCommunityIcons name="plus" size={17} color="#142035" />
                <Text style={styles.topCreateButtonText}>Nova escala</Text>
              </LinearGradient>
            </TouchableOpacity>
          )}
        </View>
        {loading ? (
          <ActivityIndicator size="large" color="#ff9800" style={{ marginTop: 40 }} />
        ) : (
          <FlatList
            data={escalas}
            keyExtractor={(item) => item.id}
            ListEmptyComponent={
              <Text style={styles.emptyText}>
                Nenhuma escala encontrada.
              </Text>
            }
            renderItem={renderItem}
            contentContainerStyle={styles.list}
            showsVerticalScrollIndicator={false}
          />
        )}

      </View>
    </LinearGradient>
  );
}

